export const questions = rows.map(([text,...options], i) => ({id:i+1,text,options,correct:'BDACBDACBDACBDACBDACBDACBDACBD'[i],section:i<6?0:i<15?1:i<22?2:3}));
export function evaluate(answers) {
 const score = questions.filter(q => answers[q.id] === q.correct).length;
 const skipped = questions.filter(q => !answers[q.id]).length;
 const grade = score>=26?5:score>=22?4:score>=17?3:2;
 return {score, skipped, wrong:30-score-skipped, grade, label:({5:'A’lo',4:'Yaxshi',3:'Qoniqarli',2:'Qoniqarsiz'})[grade],percent:(score/30*100).toFixed(1)};
}
